Whilst there are tons of tools to do S3 upload, I wanted something tuned to how I blog, particularly with a static blog that used to be a WordPress one with year/month directories for images.
Usage:
node upload_s3_images.js image1.jpg image2.jpg image3.png etc It uses your AWS credentials in ~/aws_config.json { &ldquo;accessKeyId&rdquo;: &ldquo;akid&rdquo;, &ldquo;secretAccessKey&rdquo;: &ldquo;secret&rdquo;, &ldquo;region&rdquo;: &ldquo;us-west-2&rdquo; }
It uses the bucket name and root upload directory from ./s3_blog_config.json {&ldquo;bucket&rdquo;: &ldquo;conoroneill.net&rdquo;, &ldquo;rootUploadDir&rdquo;: &ldquo;wp-content/uploads/&rdquo;}
So if I have a file called s3_upload.jpg on my Desktop and I invoke as follows:
node upload_s3_images.js ~/Desktop/s3_upload.jpg I end up with a file at: https://d2j17b10ywb1i7.cloudfront.net/wp-content/uploads/2014/06/s3_upload.jpg
// upload_s3_images.js // Upload a space separated list of images to an S3 bucket for use by your Harp.js static blog // node upload_s3_images.js image1.jpg image2.jpg image3.png etc // Uses your AWS credentials in ~/aws_config.json { &#34;accessKeyId&#34;: &#34;akid&#34;, &#34;secretAccessKey&#34;: &#34;secret&#34;, &#34;region&#34;: &#34;us-west-2&#34; } // Uses bucket name and root upload directory from ./s3_blog_config.json {&#34;bucket&#34;: &#34;conoroneill.net&#34;, &#34;rootUploadDir&#34;: &#34;wp-content/uploads/&#34;} // My blog is exported from WordPress so it uses /wp-content/uploads/year/month/ as the directory stucture // Copyright (C) 2014 Conor O&#39;Neill // Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the &#34;Software&#34;), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions: // The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software. // THE SOFTWARE IS PROVIDED &#34;AS IS&#34;, WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE. var AWS = require(&#39;aws-sdk&#39;); var fs = require(&#39;fs&#39;); var userHome = process.env.HOME || process.env.HOMEPATH || process.env.USERPROFILE; AWS.config.loadFromPath(userHome + &#39;/aws_config.json&#39;); var blogConfig = require(&#39;./s3_blog_config.json&#39;); var fileList = process.argv.slice(2); fileList.forEach(function (val, index, array) { var fileName = val; var currentTime = new Date(); var currentYear = currentTime.getFullYear(); var currentMonth = (&#34;0&#34; + (currentTime.getMonth() + 1)).slice(-2); var uploadName = blogConfig.rootUploadDir + currentYear + &#39;/&#39; + currentMonth + &#39;/&#39; + fileName.split(&#39;/&#39;).pop(); var fileBuffer = fs.readFileSync(fileName); var metaData = getContentTypeByFile(fileName); var s3 = new AWS.S3(); var params = {Bucket: blogConfig.bucket, Key: uploadName, Body: fileBuffer, ContentType: metaData}; s3.putObject(params, function(err, data) { if (err) console.log(err) else console.log(&#34;Successfully uploaded: &#34; + blogConfig.blogS3Url + blogConfig.bucket + &#34;/&#34; + uploadName); }); }); function getContentTypeByFile(fileName) { var rc = &#39;application/octet-stream&#39;; var fn = fileName.toLowerCase(); if (fn.indexOf(&#39;.html&#39;) &gt;= 0) rc = &#39;text/html&#39;; else if (fn.indexOf(&#39;.css&#39;) &gt;= 0) rc = &#39;text/css&#39;; else if (fn.indexOf(&#39;.json&#39;) &gt;= 0) rc = &#39;application/json&#39;; else if (fn.indexOf(&#39;.js&#39;) &gt;= 0) rc = &#39;application/x-javascript&#39;; else if (fn.indexOf(&#39;.png&#39;) &gt;= 0) rc = &#39;image/png&#39;; else if (fn.indexOf(&#39;.jpg&#39;) &gt;= 0) rc = &#39;image/jpg&#39;; return rc; } Source is here on GitHub.
I hope you find it useful.

